package com.example.lending.application.service;

import com.example.lending.application.port.in.DiscardBookUseCase;
import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.SaveBookPort;
import com.example.lending.domain.Book;
import com.example.lending.domain.BookNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.UUID;

@Service
@Transactional
public class DiscardBookService implements DiscardBookUseCase {

    private final LoadBookPort loadBookPort;
    private final SaveBookPort saveBookPort;

    public DiscardBookService(LoadBookPort loadBookPort, SaveBookPort saveBookPort) {
        this.loadBookPort = loadBookPort;
        this.saveBookPort = saveBookPort;
    }

    @Override
    public Book discardBook(UUID bookId) {
        Book book = loadBookPort.loadBook(bookId).orElseThrow(() -> new BookNotFoundException(bookId));
        book.discard();
        saveBookPort.saveBook(book);
        return book;
    }
}
package com.example.lending.application.service;

import com.example.lending.application.port.in.LoanBookUseCase;
import com.example.lending.application.port.out.CheckCreditPort;
import com.example.lending.application.port.out.CountMemberLoansPort;
import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.application.port.out.LoadReservationsPort;
import com.example.lending.application.port.out.SaveBookPort;
import com.example.lending.application.port.out.SaveLoanPort;
import com.example.lending.application.port.out.SaveReservationPort;
import com.example.lending.domain.Book;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.CreditCheck;
import com.example.lending.domain.Loan;
import com.example.lending.domain.Member;
import com.example.lending.domain.MemberNotFoundException;
import com.example.lending.domain.Reservation;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.util.Optional;

@Service
@Transactional
public class LoanBookService implements LoanBookUseCase {

    private final LoadBookPort loadBookPort;
    private final SaveBookPort saveBookPort;
    private final SaveLoanPort saveLoanPort;
    private final LoadMemberPort loadMemberPort;
    private final CountMemberLoansPort countMemberLoansPort;
    private final LoadReservationsPort loadReservationsPort;
    private final SaveReservationPort saveReservationPort;
    private final CheckCreditPort checkCreditPort;

    public LoanBookService(LoadBookPort loadBookPort, SaveBookPort saveBookPort, SaveLoanPort saveLoanPort,
                           LoadMemberPort loadMemberPort, CountMemberLoansPort countMemberLoansPort,
                           LoadReservationsPort loadReservationsPort, SaveReservationPort saveReservationPort,
                           CheckCreditPort checkCreditPort) {
        this.loadBookPort = loadBookPort;
        this.saveBookPort = saveBookPort;
        this.saveLoanPort = saveLoanPort;
        this.loadMemberPort = loadMemberPort;
        this.countMemberLoansPort = countMemberLoansPort;
        this.loadReservationsPort = loadReservationsPort;
        this.saveReservationPort = saveReservationPort;
        this.checkCreditPort = checkCreditPort;
    }

    @Override
    public Loan loanBook(LoanBookCommand command) {
        Member member = loadMemberPort.loadMember(command.memberId())
                .orElseThrow(() -> new MemberNotFoundException(command.memberId()));
        member.assertCanBorrow(countMemberLoansPort.countLoans(member.getId()));
        Book book = loadBookPort.loadBook(command.bookId())
                .orElseThrow(() -> new BookNotFoundException(command.bookId()));
        book.markLoaned();
        Optional<Reservation> claimed = loadReservationsPort.loadQueue(book.getId()).claimFor(member.getId());
        CreditCheck creditCheck = checkCreditPort.checkCredit(member);
        Loan loan = Loan.start(book.getId(), command.memberId(),
                command.loanedAt() != null ? command.loanedAt() : LocalDate.now(), creditCheck);
        saveBookPort.saveBook(book);
        saveLoanPort.saveLoan(loan);
        claimed.ifPresent(saveReservationPort::saveReservation);
        return loan;
    }
}
package com.example.lending.application.service;

import com.example.lending.application.port.in.ReturnBookUseCase;
import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.LoadLoanPort;
