import java.util.List;
import java.util.UUID;

@RestController
@RequestMapping("/members")
public class MemberController {

    private final RegisterMemberUseCase registerMemberUseCase;
    private final GetMemberUseCase getMemberUseCase;
    private final GetMemberLoansUseCase getMemberLoansUseCase;
    private final GetMemberLoanHistoryUseCase getMemberLoanHistoryUseCase;
    private final SuspendMemberUseCase suspendMemberUseCase;

    public MemberController(RegisterMemberUseCase registerMemberUseCase, GetMemberUseCase getMemberUseCase,
                            GetMemberLoansUseCase getMemberLoansUseCase,
                            GetMemberLoanHistoryUseCase getMemberLoanHistoryUseCase,
                            SuspendMemberUseCase suspendMemberUseCase) {
        this.registerMemberUseCase = registerMemberUseCase;
        this.getMemberUseCase = getMemberUseCase;
        this.getMemberLoansUseCase = getMemberLoansUseCase;
        this.getMemberLoanHistoryUseCase = getMemberLoanHistoryUseCase;
        this.suspendMemberUseCase = suspendMemberUseCase;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public MemberResponse registerMember(@RequestBody RegisterMemberRequest request) {
        return MemberResponse.from(registerMemberUseCase.registerMember(new RegisterMemberCommand(request.memberId(), request.name())));
    }

    @GetMapping("/{memberId}")
    public MemberResponse getMember(@PathVariable UUID memberId) {
        return MemberResponse.from(getMemberUseCase.getMember(memberId));
    }

    @PostMapping("/{memberId}/suspend")
    public void suspend(@PathVariable UUID memberId) {
        suspendMemberUseCase.suspend(memberId);
    }

    @PostMapping("/{memberId}/unsuspend")
    public void unsuspend(@PathVariable UUID memberId) {
        suspendMemberUseCase.unsuspend(memberId);
    }

    @GetMapping("/{memberId}/loans")
    public MemberLoansResponse getMemberLoans(@PathVariable UUID memberId,
                                              @RequestParam(defaultValue = "0") int page,
                                              @RequestParam(defaultValue = "20") int size) {
        return MemberLoansResponse.from(getMemberLoansUseCase.getActiveLoans(new GetMemberLoansQuery(memberId, page, size)));
    }

    @GetMapping("/{memberId}/loans/history")
    public List<LoanHistoryResponse> getMemberLoanHistory(@PathVariable UUID memberId) {
        return getMemberLoanHistoryUseCase.getLoanHistory(memberId).stream().map(LoanHistoryResponse::from).toList();
    }
}
