        this.reservationId = reservationId;
        this.bookId = bookId;
        this.memberId = memberId;
        this.fulfilled = fulfilled;
    }

    public UUID getReservationId() {
        return reservationId;
    }

    public UUID getBookId() {
        return bookId;
    }

    public UUID getMemberId() {
        return memberId;
    }

