import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MemberSuspensionIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void suspended_member_cannot_borrow_until_unsuspended() throws Exception {
        String memberId = register("/members", "{\"name\":\"김민지\"}", "memberId");
        String bookId = register("/books", "{\"title\":\"클린 코드\"}", "id");
        String loan = "{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId + "\"}";

        mockMvc.perform(get("/members/" + memberId)).andExpect(jsonPath("$.suspended").value(false));

        mockMvc.perform(post("/members/" + memberId + "/suspend")).andExpect(status().isOk());
        mockMvc.perform(get("/members/" + memberId)).andExpect(jsonPath("$.suspended").value(true));
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loan))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("MEMBER_SUSPENDED"));

        mockMvc.perform(post("/members/" + memberId + "/unsuspend")).andExpect(status().isOk());
        mockMvc.perform(get("/members/" + memberId)).andExpect(jsonPath("$.suspended").value(false));
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loan))
                .andExpect(status().isCreated());
    }

    @Test
    void unknown_member_returns_404() throws Exception {
        mockMvc.perform(post("/members/" + UUID.randomUUID() + "/suspend")).andExpect(status().isNotFound());
        mockMvc.perform(post("/members/" + UUID.randomUUID() + "/unsuspend")).andExpect(status().isNotFound());
    }

    private String register(String path, String json, String idField) throws Exception {
        String body = mockMvc.perform(post(path).contentType(MediaType.APPLICATION_JSON).content(json))
                .andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get(idField).asText();
    }
}
