package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.out.LoadAuditEntriesPort;
import com.example.lending.application.port.out.SaveAuditEntryPort;
import com.example.lending.domain.AuditEntry;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.UUID;

@Component
public class AuditPersistenceAdapter implements SaveAuditEntryPort, LoadAuditEntriesPort {

    private final AuditJpaRepository auditJpaRepository;

    public AuditPersistenceAdapter(AuditJpaRepository auditJpaRepository) {
        this.auditJpaRepository = auditJpaRepository;
    }

    @Override
    public void saveAuditEntry(AuditEntry entry) {
        auditJpaRepository.save(new AuditJpaEntity(entry.action(), entry.targetId(), entry.memberId(),
                entry.occurredAt()));
    }

    @Override
    public List<AuditEntry> loadByTargetId(UUID targetId) {
        return auditJpaRepository.findByTargetIdOrderBySeqAsc(targetId).stream()
                .map(e -> new AuditEntry(e.getAction(), e.getTargetId(), e.getMemberId(), e.getOccurredAt()))
                .toList();
    }
}
