package com.example.lending.domain;

import java.time.Instant;
import java.util.UUID;

/** 상태 변경 작업 한 건의 감사 기록. memberId 는 작업 주체가 없으면 null 이다. */
public record AuditEntry(AuditAction action, UUID targetId, UUID memberId, Instant occurredAt) {

    public static AuditEntry now(AuditAction action, UUID targetId, UUID memberId) {
        return new AuditEntry(action, targetId, memberId, Instant.now());
    }
}
